package com.dronefleet.service;import com.dronefleet.domain.*;import java.io.*;import java.nio.charset.StandardCharsets;public final class ExportService{public void deliveriesCsv(java.io.File file,java.util.List<Delivery> ds)throws IOException{try(PrintWriter out=new PrintWriter(new OutputStreamWriter(new FileOutputStream(file),StandardCharsets.UTF_8))){out.println("Delivery ID,Package ID,Drone ID,Status,Weight kg,Distance km,Charge LKR,Battery Used %,Created At,Completed At");for(Delivery d:ds)out.printf("%d,%d,%s,%s,%.2f,%.2f,%.2f,%.2f,%s,%s%n",d.id(),d.item().id(),d.droneId()==null?"":d.droneId(),d.status(),d.item().weight(),d.item().distance(),d.charge(),d.batteryUsed(),d.createdAt(),d.completedAt()==null?"":d.completedAt());}}}
